"""Run every case against vm.py and report. Do not edit this file."""

import pathlib
import subprocess
import sys

CASES = pathlib.Path(__file__).parent / "cases"


def main() -> int:
    if not pathlib.Path("vm.py").exists():
        print("vm.py does not exist yet")
        print("SCORE 0", len(list(CASES.glob("*.pbl"))))
        return 1

    passed, failed = 0, []
    for case in sorted(CASES.glob("*.pbl")):
        expected = case.with_suffix(".out").read_text()
        try:
            done = subprocess.run(
                [sys.executable, "vm.py", str(case)],
                capture_output=True, text=True, timeout=10,
            )
            actual = done.stdout
        except subprocess.TimeoutExpired:
            actual = "<timed out>"
        if actual == expected:
            passed += 1
        else:
            failed.append((case.name, expected, actual))

    total = passed + len(failed)
    for name, want, got in failed[:12]:
        print(f"FAIL {name}\n  want {want!r}\n  got  {got!r}")
    if len(failed) > 12:
        print(f"... and {len(failed) - 12} more failing")
    print(f"SCORE {passed} {total}")
    return 0 if not failed else 1


if __name__ == "__main__":
    raise SystemExit(main())
